const nswBoatRampsLayer = L.markerClusterGroup({ maxClusterRadius: 40 });

const rampIcon = L.divIcon({
  className: "custom-marker",
  html: '<div style="background:#006400; width:12px; height:12px; border-radius:50%; border:2px solid white;"></div>',
  iconSize: [16, 16]
});

nswBoatRamps.forEach(function (m) {
  L.marker([m.lat, m.lng], { icon: rampIcon })
    .bindPopup(`<strong>${m.name}</strong><br>${m.suburb} - ${m.waterway}<br>Lanes: ${m.lanes}, Trailer spaces: ${m.trailerSpaces}<br>Condition: ${m.condition}<br>Facilities: ${m.facilities}`)
    .addTo(nswBoatRampsLayer);
});
